<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cambiarEstadoPersonaFamiliar, descargarSustentoFamiliar, guardarPersonaFamiliar, listarOpcionesPersonaFamiliares, listarPersonaFamiliares } from '../services/personaFamiliares'
import type { FamiliarPersona, PersonaFamiliar, PersonaFamiliarPayload } from '../interfaces/personaFamiliares.interface'
const rows=ref<PersonaFamiliar[]>([]),personas=ref<FamiliarPersona[]>([]),tipos=ref<string[]>([]),sexos=ref<string[]>([]),vinculos=ref<string[]>([]),criterio=ref(''),personaFiltro=ref<number|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),maxMb=ref(20),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null);const defaults:PersonaFamiliarPayload={persona_id:0,apellidopaterno:'',apellidomaterno:'',nombres:'',tipoidentidad:'DNI',numerodocumento:'',sexo:null,fechanacimiento:null,vinculo:'',sustento:null};const form=reactive<PersonaFamiliarPayload>({...defaults});const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.';const date=(v:string|null)=>v?new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('es-PE'):'—'
async function options(){try{const r=await listarOpcionesPersonaFamiliares();personas.value=r.personas;tipos.value=r.tipos_identidad;sexos.value=r.sexos;vinculos.value=r.vinculos;maxMb.value=r.maximo_archivo_mb||20}catch(v){error.value=message(v)}}async function load(reset=false){if(reset)page.value=1;loading.value=true;error.value='';try{const r=await listarPersonaFamiliares(criterio.value,page.value,personaFiltro.value);rows.value=r.data;total.value=r.total;page.value=r.current_page;lastPage.value=r.last_page}catch(v){error.value=message(v)}finally{loading.value=false}}
function openCreate(){editing.value=null;Object.assign(form,defaults,{persona_id:personaFiltro.value??0});error.value='';modal.value=true}function openEdit(x:PersonaFamiliar){editing.value=x.id;Object.assign(form,{persona_id:x.persona_id,apellidopaterno:x.apellidopaterno,apellidomaterno:x.apellidomaterno,nombres:x.nombres,tipoidentidad:x.tipoidentidad,numerodocumento:x.numerodocumento,sexo:x.sexo,fechanacimiento:x.fechanacimiento?.slice(0,10)??null,vinculo:x.vinculo,sustento:null});error.value='';modal.value=true}function fileSelected(e:Event){form.sustento=(e.target as HTMLInputElement).files?.[0]??null}
function validate(){if(!form.persona_id)return 'Debe seleccionar al trabajador.';if(!form.apellidopaterno.trim()||!form.apellidomaterno.trim()||!form.nombres.trim())return 'Los apellidos y nombres son obligatorios.';if(!tipos.value.includes(form.tipoidentidad))return 'Seleccione un tipo de identidad válido.';if(!form.numerodocumento.trim()||form.numerodocumento.trim().length>15)return 'El documento es obligatorio y admite hasta 15 caracteres.';if(form.sexo&&!sexos.value.includes(form.sexo))return 'Seleccione un sexo válido.';if(!vinculos.value.includes(form.vinculo))return 'Seleccione el vínculo familiar.';if(form.sustento&&(form.sustento.type!=='application/pdf'||form.sustento.size>maxMb.value*1024*1024))return `El sustento debe ser PDF y no superar ${maxMb.value} MB.`;return ''}
async function save(){const issue=validate();if(issue)return void(error.value=issue);saving.value=true;error.value='';try{await guardarPersonaFamiliar(editing.value,{...form,apellidopaterno:form.apellidopaterno.trim(),apellidomaterno:form.apellidomaterno.trim(),nombres:form.nombres.trim(),numerodocumento:form.numerodocumento.trim()});modal.value=false;success.value=`Familiar ${editing.value?'actualizado':'registrado'} correctamente.`;await load()}catch(v){error.value=message(v)}finally{saving.value=false}}async function toggle(x:PersonaFamiliar){const action=x.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} a ${x.nombres}?`))return;try{const r=await cambiarEstadoPersonaFamiliar(x.id);x.estado=r.estado;success.value=r.message??`Familiar ${r.estado?'activado':'desactivado'} correctamente.`}catch(v){error.value=message(v)}}async function download(x:PersonaFamiliar){try{await descargarSustentoFamiliar(x.id)}catch(v){error.value=message(v)}}function move(v:number){if(v<1||v>lastPage.value)return;page.value=v;load()}onMounted(()=>Promise.all([options(),load()]))
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Familiares por trabajador</nav><header class="hero"><div class="mark">FA</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Familiares por trabajador</h1><p>Registro de familiares, vínculos, documentos de identidad y sustentos.</p></div><strong>{{total}} familiares</strong></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><label>Trabajador<select v-model="personaFiltro" @change="load(true)"><option :value="null">Todos</option><option v-for="x in personas" :key="x.id" :value="x.id">{{x.nombre_completo}} · {{x.dni||'Sin DNI'}}</option></select></label><form @submit.prevent="load(true)"><label>Buscar<input v-model.trim="criterio" placeholder="Nombre, documento, vínculo o trabajador"></label><button>Buscar</button></form><button class="new" @click="openCreate">Registrar familiar</button></section><section class="table-card"><header><small>ENTORNO FAMILIAR</small><h2>Familiares registrados</h2></header><div v-if="loading" class="empty">Consultando familiares…</div><div v-else-if="!rows.length" class="empty">No se encontraron familiares.</div><div v-else class="scroll"><table><thead><tr><th>Trabajador</th><th>Familiar</th><th>Vínculo</th><th>Documento</th><th>Sexo</th><th>Nacimiento</th><th>Sustento</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="x in rows" :key="x.id"><td><b>{{x.persona?.nombre_completo??`Persona #${x.persona_id}`}}</b><small>DNI: {{x.persona?.dni||'—'}}</small></td><td>{{x.apellidopaterno}} {{x.apellidomaterno}}, {{x.nombres}}</td><td>{{x.vinculo}}</td><td><b>{{x.tipoidentidad}}</b><small>{{x.numerodocumento}}</small></td><td>{{x.sexo||'—'}}</td><td>{{date(x.fechanacimiento)}}</td><td><button v-if="x.sustento" class="link" @click="download(x)">Descargar PDF</button><span v-else>—</span></td><td><span :class="x.estado?'active':'inactive'">{{x.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="openEdit(x)">Editar</button><button :class="x.estado?'disable':'enable'" @click="toggle(x)">{{x.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="move(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page>=lastPage" @click="move(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">FA</div><div><small>{{editing?'ACTUALIZAR FAMILIAR':'NUEVO FAMILIAR'}}</small><h2>{{editing?'Editar':'Registrar'}} familiar</h2></div><button type="button" class="close" @click="modal=false">×</button></header><div class="grid"><label class="full">Trabajador *<select v-model="form.persona_id" :disabled="editing!==null"><option :value="0">Seleccione</option><option v-for="x in personas" :key="x.id" :value="x.id">{{x.nombre_completo}} · DNI {{x.dni||'—'}}</option></select></label><label>Apellido paterno *<input v-model="form.apellidopaterno" maxlength="100"></label><label>Apellido materno *<input v-model="form.apellidomaterno" maxlength="100"></label><label class="full">Nombres *<input v-model="form.nombres" maxlength="100"></label><label>Tipo de identidad *<select v-model="form.tipoidentidad"><option v-for="x in tipos" :key="x">{{x}}</option></select></label><label>Número de documento *<input v-model="form.numerodocumento" maxlength="15"></label><label>Sexo<select v-model="form.sexo"><option :value="null">Sin especificar</option><option v-for="x in sexos" :key="x">{{x}}</option></select></label><label>Fecha de nacimiento<input v-model="form.fechanacimiento" type="date"></label><label class="full">Vínculo *<select v-model="form.vinculo"><option value="">Seleccione</option><option v-for="x in vinculos" :key="x">{{x}}</option></select></label><label class="full">Sustento PDF<input type="file" accept="application/pdf" @change="fileSelected"><small>Máximo {{maxMb}} MB{{editing?' · vacío conserva el archivo actual':''}}.</small></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#9a536b;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;flex:none;border-radius:10px;color:#fff;background:var(--accent);font-size:.6rem;font-weight:800}.hero small,.table-card small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero>strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#f8edf1;font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:12px;display:flex;align-items:end;gap:7px;border-radius:9px;background:#fff}.filters>label{width:310px}.filters form{display:flex;align-items:end;gap:5px;margin-right:auto}.filters form label{width:330px}.filters label,.dialog label{font-size:.5rem}.filters input,.filters select,.dialog input,.dialog select{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.filters button,.table-card>footer button,.dialog footer button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.soft{color:#64727a!important;background:#edf1f3!important}.new{background:#287154!important}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;min-width:1150px;border-collapse:collapse;font-size:.48rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left;vertical-align:middle}th{color:#fff;background:#526d79}td>b,td>small{display:block}.active,.inactive{display:inline-block;padding:4px 7px;border-radius:10px}.active{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.actions{display:flex;gap:4px}.actions button,.link{padding:6px 8px;border:0;border-radius:5px;font-size:.44rem}.edit,.link{color:#82445a;background:#f8e9ee}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;align-items:center;justify-content:center;gap:10px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:18px;display:grid;place-items:center;background:#172b3daa}.dialog{width:min(820px,100%);max-height:94vh;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff;overflow:auto}.dialog>header{display:flex;align-items:center;gap:10px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.close{margin-left:auto;border:0;color:#59666c;background:none;font-size:1.3rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px 12px}.grid label small{display:block;margin-top:3px;color:#7e8a90}.full{grid-column:1/-1}.dialog>footer{margin-top:18px;display:flex;justify-content:flex-end;gap:7px}@media(max-width:900px){.hero,.filters,.filters form{flex-wrap:wrap}.hero>strong{margin-left:0}.filters>label,.filters form,.filters form label{width:100%}.grid{grid-template-columns:1fr}.full{grid-column:auto}}
